/**
 * <div id="swoole-atomic.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">Swoole\Atomic::__construct</h1>  <p class="verinfo">(PECL swoole &gt;= 1.9.0)</p><p class="refpurpose"><span class="refname">Swoole\Atomic::__construct</span> — <span class="dc-title">Construct a swoole atomic object.</span></p> </div> <div class="refsect1 description" id="refsect1-swoole-atomic.construct-description">  <h3 class="title">说明</h3>  <div class="constructorsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Swoole\Atomic::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$value</span><span class="initializer"> = ?</span></span>)</div>  <p class="para rdfs-comment">    Swoole atomic object is an integer variable allows any processor to atomically test and modify.    It is implemented based on CPU atomic instructions. The Swoole atomic variables have to     defined before swoole_server-&gt;start.  </p>  <p class="para">    Compare-and-swap (CAS) is an atomic instruction used in multithreading to achieve synchronization.     It compares the content of a memory location with a given value and, only if they are the same,     modifies the content of that memory location to a new given value.  </p> </div> <div class="refsect1 parameters" id="refsect1-swoole-atomic.construct-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">value</span></dt>    <dd>     <p class="para">      The value of the atomic object.     </p>    </dd>     </dl> </div></div>
 */
    public function __construct(int $value = 0) {}

