    /**
 * <div id="swoole-atomic.cmpset" class="refentry"> <div class="refnamediv">  <h1 class="refname">Swoole\Atomic::cmpset</h1>  <p class="verinfo">(PECL swoole &gt;= 1.9.0)</p><p class="refpurpose"><span class="refname">Swoole\Atomic::cmpset</span> — <span class="dc-title">Compare and set the value of the atomic object.</span></p> </div> <div class="refsect1 description" id="refsect1-swoole-atomic.cmpset-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Swoole\Atomic::cmpset</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$cmp_value</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$new_value</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>  <p class="para rdfs-comment">  </p> </div> <div class="refsect1 parameters" id="refsect1-swoole-atomic.cmpset-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">cmp_value</span></dt>    <dd>     <p class="para">      The value to compare with the current value of the atomic object.     </p>    </dd>          <dt><span class="parameter" style="color:#3A95FF">new_value</span></dt>    <dd>     <p class="para">      The value to set to the atomic object if the cmp_value is the same as the current value of      the atomic object.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="r